function applyLightingRig(){if(!key)return;const desert=!!props.drive&&props.roadMap==='desert';key.target.position.set(0,desert?8.28:0,0);const shadowSpan=desert?24:props.drive?7:4.2;const shadowSize=props.drive?1024:2048;if(key.shadow.mapSize.x!==shadowSize){key.shadow.map?.dispose();key.shadow.map=null;key.shadow.mapSize.set(shadowSize,shadowSize)}key.shadow.intensity=desert?.68:1;key.shadow.camera.left=-shadowSpan;key.shadow.camera.right=shadowSpan;key.shadow.camera.top=shadowSpan;key.shadow.camera.bottom=-shadowSpan;key.shadow.camera.far=120;key.shadow.camera.updateProjectionMatrix();key.shadow.normalBias=desert?.035:0;key.shadow.bias=desert?-.00008:-.001;if(props.drive&&props.roadMap==='desert'){key.position.set(35.4,49.267,25.74);key.intensity=3.2;key.color.set('#ffffff');key.shadow.radius=3;fill.position.set(12,20,-22);fill.intensity=3;fill.color.set('#f6f5f0');ambient.color.set('#e4e8e9');ambient.groundColor.set('#e4e8ea');ambient.intensity=.16;scene.environmentIntensity=.55;return}if(isMountain()){const winter=props.roadMap==='winter';key.position.set(-28, winter?44:23,-65);key.intensity=winter?.78:2.35;key.color.set(winter?'#b9d1f5':'#fff0db');key.shadow.radius=winter?5:3;key.shadow.intensity=winter?.38:.7;key.shadow.camera.left=-18;key.shadow.camera.right=18;key.shadow.camera.top=18;key.shadow.camera.bottom=-18;key.shadow.camera.updateProjectionMatrix();key.shadow.normalBias=.025;key.shadow.bias=-.00008;fill.position.set(10,15,-12);fill.intensity=winter?5:3;fill.color.set('#d7e4f2');ambient.color.set('#d7e4f3');ambient.groundColor.set(winter?'#b2bec9':'#656c69');ambient.intensity=winter?.5:.46;scene.environmentIntensity=winter?.6:.55;return}if(isDaylight()){key.intensity=2.4;key.color.set('#fff6e5');fill.color.set('#f0f7ff');fill.intensity=12;ambient.color.set('#e1f0ff');ambient.groundColor.set('#776c55');ambient.intensity=.65;scene.environmentIntensity=.9;return}if(props.drive){key.intensity=.35;key.color.set('#c8d7f0');fill.intensity=2;fill.color.set('