function applyLights(){if(!car)return;if('setLights' in car&&typeof car.setLights==='function')car.setLights((introLighting?.front??Number(state.headlights.value))>0,(introLighting?.rear??Number(state.taillights.value))>0,introLighting?.front??Number(state.headlights.value),introLighting?.rear??Number(state.taillights.value));else car.white.emissiveIntensity=2*(introLighting?.front??Number(state.headlights.value));lampDynamics?.configure(state.quality.value,state.shadows.value,!!props.drive)}
