watch(()=>state.car.value.id,()=>{if(!scene||!car)return;engineAudio.dispose();doorAudio.dispose();doorAudio=createDoorAudio();void doorAudio.preload();engineAudio=createEngineAudio(state.car.value.id==='tourbillon'?'tourbillon':state.car.value.id==='gt3'?'gt3':state.car.value.id==='revuelto'?'revuelto':state.car.value.id==='750s'?'750s':state.car.value.id==='valhalla'?'valhalla':state.car.value.id==='jesko'?'jesko':state.car.value.id==='amg'?'amg':state.car.value.shape===8);if(props.drive&&state.engine.value)engineAudio.start();stopIntro();const old=car;gsap.to(old.root.scale,{x:.01,y:.01,z:.01,duration:.3,async onComplete(){scene.remove(old.root);old.root.traverse(o=>{if(o instanceof T.SpotLight||o instanceof T.DirectionalLight)o.shadow.map?.dispose()});old.dispose();try{const loaded=await loadVehicle(state.car.value.shape,n=>emit('progress',n));if(stopped){loaded.dispose();return}car=loaded;installPaintFinish(car.body);installLivery(car.body);if('secondaryPaint' in car&&car.secondaryPaint instanceof T.MeshStandardMaterial)installLivery(car.secondaryPaint);if(props.drive)glassFrost=installGlassFrost(car.root);look.anchor.set(...(state.car.value.shape===0?[.16,.90,.364]:state.car.value.id==='tourbillon'?[.03,.98,-.36]:state.car.value.id==='gt3'?[.10,1.02,.34]:state.car.value.id==='750s'?[-.02,.95,.32]:state.car.value.id==='amg'?[.08,1.13,.37]:[.02,1.04,.35]) as [number,number,number]);driveLook.anchor.copy(look.anchor);applyConfiguration();scene.add(car.root);syncCarEnvironment();if(props.drive){tyreContact=createTyreContact(car.root,car.wheels,(x,z,d)=>motionRoad?.heightAt(x,z,d)??.007,()=>2.7);wheelBlur=installWheelBlur(car.wheels);reset()}car.root.scale.setScalar(.01);
  // Upload textures and link the new programs before the first frame draws the car (a cold draw stalls for seconds).
  preparing=true;try{await warmScene()}finally{preparing=false}if(stopped)return
  emit("progress",100);emit("ready");gsap.to(car.root.scale,{x:1,y:1,z:1,duration:.7})}catch(e){emit('error','Vehicle could not load. Please retry.')}}})})
onBeforeUnmount(()=>{state.sceneReady.value=false;performanceState.value.visible=false;clearTimeout(preloadTimer);intro?.stop();stopped=true;motionRoad?.dispose();motionRoad=undefined;roadAssets?.dispose();gsap.killTweensOf(windowMotion);gsap.killTweensOf(doorMotion);engineAudio.dispose();doorAudio.dispose();cancelAnimationFrame(frame);cancelAnimationFrame(resizeFrame);transition?.kill();resize?.disconnect();window.removeEventListener('keydown',keyboard);window.removeEventListener('keyup',release);window.removeEventListener('blur',blur);controls?.dispose();if(renderer){renderer.domElement.removeEventListener('pointerdown',pointerDown);renderer.domElement.removeEventListener('pointermove',pointerMove);renderer.domElement.removeEventListener('pointerup',pointerUp);renderer.domElement.removeEventListener('pointercancel',pointerUp)}gsap.killTweensOf(camera?.position);if(car){car.root.traverse(o=>{if(o instanceof T.SpotLight)o.shadow.map?.dispose()});car.doors.forEach(d=>gsap.killTweensOf(d.rotation));scene.remove(car.root);car.dispose()}scene?.traverse(o=>{if(o instanceof T.Mesh){o.geometry.dispose();if(o instanceof T.InstancedMesh)o.dispose();(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>{for(const value of Object.values(m))if(value instanceof T.Texture)value.dispose();m.dispose()})}});grid?.geometry.dispose();if(grid)(Array.isArray(grid.material)?grid.material:[grid.material]).forEach(m=>m.dispose());studioFloor?.dispose();desertSky?.dispose();envTarget?.dispose();saltEnvironment?.dispose();mountainSky?.dispose();post?.dispose();pmrem?.dispose();renderer?.dispose()})
// Photo mode snapshot: the next frame renders at up to twice the screen resolution (at most 4K wide) and is saved as a
// PNG straight from the canvas, so no interface is in it.
let photoShot:(()=>void)|undefined
const frameRatios:Record<string,number>={'16:9':16/9,'2.39:1':2.39,'4:5':.8,'1:1':1}
function capturePhoto(){return new Promise<Blob|null>(resolve=>{if(!renderer||!el.value){resolve(null);return}
 const w=el.value.clientWidth,h=el.value.clientHeight,ratio=renderer.getPixelRatio(),target=Math.max(ratio,Math.min(ratio*2,3840/w))
 renderer.setPixelRatio(target);renderer.setSize(w,h,false);post?.resize(w,h)
 photoShot=()=>{
  // the chosen frame is cut from the middle of the picture, exactly as the photo mode's frame shows it
  const source=renderer.domElement,aspect=frameRatios[state.photoSettings.value.frame],cw=aspect?Math.round(Math.min(source.width,source.height*aspect)):source.width,ch=aspect?Math.round(cw/aspect):source.height
  const cut=document.createElement('canvas');cut.width=cw;cut.height=ch;cut.getContext('2d')!.drawImage(source,(source.width-cw)/2,(source.height-ch)/2,cw,ch,0,0,cw,ch)
  renderer.setPixelRatio(ratio);renderer.setSize(w,h,false);post?.resize(w,h);cut.toBlob(blob=>resolve(blob),'image/png')}})}
// Photo mode finishing: lens (35 mm equivalent), exposure, colour look, vignette and depth of field focused on the car.
const looks={natural:0,warm:1,cool:2,cinema:3,mono:4,film:5} as const
let photoExposureBase=1,photoFovBase=0
const carCentre=new T.Vector3()
function applyPhotoFrame(){
 if(!state.photoMode.value||!car||!camera){return}
 const p=state.photoSettings.value
 if(p.lens>0){const fov=2*Math.atan(12/p.lens)*180/Math.PI;if(Math.abs(camera.fov-fov)>.01){camera.fov=fov;camera.updateProjectionMatrix()}}
 renderer.toneMappingExposure=photoExposureBase*Math.pow(2,p.exposure)
 carCentre.copy(car.root.position).y+=.6
 post?.setPhoto({look:looks[p.look]??0,vignette:p.vignette,blur:p.blur,focus:camera.position.distanceTo(carCentre)})
}
// Headlights follow the time of day: on at night, off by day (the tunnel keeps whatever the driver chose).
// Wet or snowy roads: less grip, a softer pull and a lower cruising speed.
function applySurface(){const w=state.weather.value,snowing=props.roadMap==='winter'&&w.snow,raining=(props.roadMap==='desert'||props.roadMap==='mountain')&&w.rain;transmission?.setSurface?.(snowing?.55:raining?.68:1)}
function autoLamps(){applySurface();if(!props.drive||props.roadMap==='tunnel')return;const night=skyMode().time==='night';state.headlights.value=night;state.taillights.value=night}
// A new time of day or weather rebuilds the sky and its environment, which recompiles the car's materials: the loading
// curtain covers that, and the scene is warmed before it is shown again.
async function changeWeather(){if(!props.drive||!car||stopped)return;const version=++mapVersion;mapLoading=true;state.sceneReady.value=false;emit('loading','weather');emit('progress',20);try{
 await nextTick();await new Promise<void>(r=>requestAnimationFrame(()=>requestAnimationFrame(()=>r())));if(stopped||version!==mapVersion)return
 applyBackground();applyLighting();autoLamps();applyLights();emit('progress',55);await warmScene();if(stopped||version!==mapVersion)return
 mapLoading=false;state.sceneReady.value=true;emit('progress',100);emit('ready')
}catch(e){if(version===mapVersion)emit('error',e instanceof Error?e.message:'Weather could not change')}}
watch(()=>[state.weather.value.time,state.weather.value.rain,state.weather.value.winterDay],changeWeather)
watch(()=>state.weather.value.snow,()=>{if(scene&&props.drive){applyBackground();applySurface()}})
watch(()=>state.photoMode.value,on=>{if(!renderer||!camera)return;if(on){photoExposureBase=renderer.toneMappingExposure;photoFovBase=camera.fov}else{renderer.toneMappingExposure=photoExposureBase;if(photoFovBase){camera.fov=photoFovBase;camera.updateProjectionMatrix()}post?.setPhoto(null)}})
watch(()=>state.photoSettings.value.lens,lens=>{if(state.photoMode.value&&!lens&&photoFovBase&&camera){camera.fov=photoFovBase;camera.updateProjectionMatrix()}})
watch(()=>state.photoRequest.value,async()=>{const blob=await capturePhoto();if(!blob)return;const stamp=new Date().toISOString().slice(0,19).replace(/[-:T]/g,'');const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`velocity-${state.car.value.id}-${stamp}.png`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),4000)})
watch(()=>state.photoMode.value,on=>{if(on)stopIntro()})
// Cinema camera (drive): filmed shots with cuts; it keeps inside the tunnel and off the valley's cliff (+z).
const cinema=createCinemaCamera()
function cinemaRoom(){return props.roadMap==='tunnel'?{ceiling:4,left:4.6,right:4.6}:isMountain()?{ceiling:30,left:4.8,right:10}:{ceiling:30,left:12,right:12}}
watch(()=>state.cinema.value,on=>{if(on)cinema.reset();else{driveLook?.reset();if(camera){camera.fov=cam===1?76:camera.aspect<.8?65:55;camera.updateProjectionMatrix()}}})
// Body finish (configurator «Покрытие»): gloss metallic, satin matte or chrome, gliding like the colours. Clearcoat and
// iridescence never reach exactly 0, so switching never recompiles the paint shader (that would be a visible hitch).
const coats={gloss:{metalness:-1,roughness:-1,clearcoat:1,clearcoatRoughness:.065,iridescence:.22},matte:{metalness:.12,roughness:.56,clearcoat:.001,clearcoatRoughness:.4,iridescence:.001},chrome:{metalness:1,roughness:.045,clearcoat:.5,clearcoatRoughness:.03,iridescence:.08}}
function paintMaterials(){if(!car)return [] as T.MeshStandardMaterial[];const list=[car.body as T.MeshStandardMaterial];if('secondaryPaint' in car&&car.secondaryPaint instanceof T.MeshStandardMaterial)list.push(car.secondaryPaint);return list}
function applyCoat(glide:boolean){const coat=coats[state.paintCoat.value]??coats.gloss;for(const m of paintMaterials()){m.userData.glossMetalness??=m.metalness;m.userData.glossRoughness??=m.roughness;const target:Record<string,number>={metalness:coat.metalness<0?m.userData.glossMetalness:coat.metalness,roughness:coat.roughness<0?m.userData.glossRoughness:coat.roughness};if(m instanceof T.MeshPhysicalMaterial&&m.clearcoat>0)Object.assign(target,{clearcoat:coat.clearcoat,clearcoatRoughness:coat.clearcoatRoughness});if(m instanceof T.MeshPhysicalMaterial&&m.iridescence>0)target.iridescence=coat.iridescence;gsap.killTweensOf(m);if(glide&&!reduced())gsap.to(m,{...target,duration:1.4,ease:'sine.inOut'});else Object.assign(m,target)}}
watch(()=>state.paintCoat.value,()=>applyCoat(true))
// Livery (configurator): stripe type and colour; the colour glides like the paint
const liveryTypes={none:0,racing:1,speciale:2,side:3} as const
watch(()=>state.livery.value.type,type=>{liveryUniforms.liveryType.value=liveryTypes[type]??0},{immediate:true})
watch(()=>state.livery.value.colour,(v,old)=>glideColour('livery',v,old,hex=>liveryUniforms.liveryColour.value.set(hex)),{immediate:true})
defineExpose({playIntro,stopIntro,reset,cycleCamera,setPaused(value:boolean){paused=value;keys.clear()},setKey(key:string,down:boolean){down?pressDriveKey(key):keys.delete(key);if(down&&state.engine.value)engineAudio.start()}})
</script>
<template><div ref="el" class="vehicle-canvas" tabindex="0" :aria-label="props.drive?t('Перетаскивайте для осмотра дороги. C меняет камеру.','Drag to look around the road. C changes the camera.'):t('Интерактивная 3D-модель. Перетаскивайте для поворота, используйте колесо для масштаба.','Interactive three-dimensional vehicle. Drag to rotate, scroll to zoom.')"><div class="intro-curtain" :style="{opacity:introFade}" aria-hidden="true" /></div></template>











